#!/bin/bash\n\n# ============================================================================\n# QUANTUM-O.COM LOVABLE.DEV - ONE-COMMAND AUTOMATED DEPLOYMENT\n# QpiAI Quantum SDK Integration Script\n# ============================================================================\n# \n# USAGE:\n#   ./DEPLOY.sh\n#\n# REQUIREMENTS:\n#   - Python 3.10+\n#   - Node.js 18+\n#   - Git\n#   - QpiAI API Key from https://qcloud.qpiai.tech/\n#\n# WHAT THIS SCRIPT DOES:\n#   1. Verifies environment (Python, Node, Git)\n#   2. Creates project structure\n#   3. Installs all dependencies (Python + Node)\n#   4. Configures environment variables\n#   5. Initializes QpiAI Quantum SDK\n#   6. Sets up Flask backend with 15+ quantum endpoints\n#   7. Configures React frontend with quantum UI\n#   8. Creates CI/CD pipeline\n#   9. Prepares for Lovable.dev deployment\n#\n# ============================================================================\n\nset -e\n\necho \"═══════════════════════════════════════════════════════════════════════\"\necho \"  🚀 QUANTUM-O.COM - LOVABLE.DEV ONE-COMMAND DEPLOYMENT\"\necho \"  QpiAI Quantum SDK Integration\"\necho \"═══════════════════════════════════════════════════════════════════════\"\necho \"\"\n\n# Color codes\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m'\n\n# Logging functions\nlog_info() { echo -e \"${BLUE}ℹ ${NC}$1\"; }\nlog_success() { echo -e \"${GREEN}✓ ${NC}$1\"; }\nlog_error() { echo -e \"${RED}✗ ${NC}$1\"; }\nlog_warning() { echo -e \"${YELLOW}⚠ ${NC}$1\"; }\n\n# Step 1: Verify Environment\necho \"\"\nlog_info \"STEP 1: Verifying Environment\"\necho \"─────────────────────────────────────────────────────────────────────\"\n\nif ! command -v python3 &> /dev/null; then\n    log_error \"Python 3 not found\"\n    exit 1\nfi\nlog_success \"Python 3: $(python3 --version)\"\n\nif ! command -v npm &> /dev/null; then\n    log_error \"npm not found\"\n    exit 1\nfi\nlog_success \"npm: $(npm --version)\"\n\nif ! command -v git &> /dev/null; then\n    log_error \"Git not found\"\n    exit 1\nfi\nlog_success \"Git: $(git --version)\"\n\n# Step 2: Create .env\necho \"\"\nlog_info \"STEP 2: Setting Up Environment\"\necho \"─────────────────────────────────────────────────────────────────────\"\n\nif [ ! -f .env ]; then\n    log_warning \"Creating .env file\"\n    cat > .env << 'EOF'\nQPIAI_API_KEY=\"your_api_key_here\"\nQPIAI_BASE_URL=\"https://qcloud.qpiai.tech\"\nFLASK_ENV=\"production\"\nFLASK_DEBUG=\"False\"\nPORT=\"5000\"\nREACT_APP_API_URL=\"http://localhost:5000/api\"\nCORS_ORIGINS=\"http://localhost:3000,https://quantum-o.com\"\nLOG_LEVEL=\"INFO\"\nEOF\n    log_warning \"⚠ UPDATE .env with your QPIAI_API_KEY from https://qcloud.qpiai.tech/\"\nelse\n    log_success \".env file exists\"\nfi\n\n# Step 3: Python Setup\necho \"\"\nlog_info \"STEP 3: Setting Up Python Backend\"\necho \"─────────────────────────────────────────────────────────────────────\"\n\nif [ ! -d \"venv\" ]; then\n    python3 -m venv venv\nfi\n\nsource venv/bin/activate\nlog_success \"Virtual environment activated\"\n\npip install --upgrade pip > /dev/null 2>&1\nlog_info \"Installing Python packages...\"\n\npip install -q \\\n    qpiai-quantum>=1.0.0 \\\n    flask>=2.3.0 \\\n    flask-cors>=4.0.0 \\\n    python-dotenv>=1.0.0 \\\n    numpy>=1.24.0 \\\n    matplotlib>=3.7.0 \\\n    scipy>=1.10.0 \\\n    requests>=2.31.0 \\\n    gunicorn>=20.1.0\n\nlog_success \"Python packages installed\"\n\n# Step 4: Node.js Setup\necho \"\"\nlog_info \"STEP 4: Setting Up React Frontend\"\necho \"─────────────────────────────────────────────────────────────────────\"\n\nlog_info \"Installing Node.js packages...\"\nnpm install -q \\\n    react@^18.0.0 \\\n    react-dom@^18.0.0 \\\n    axios@^1.4.0 \\\n    recharts@^2.5.0 \\\n    zustand@^4.3.0\n\nlog_success \"Node.js packages installed\"\n\n# Step 5: Create directories\necho \"\"\nlog_info \"STEP 5: Creating Project Structure\"\necho \"─────────────────────────────────────────────────────────────────────\"\n\nmkdir -p backend/{routes,services,models}\nmkdir -p src/{components/quantum,pages,hooks,utils}\nmkdir -p logs tests\n\nlog_success \"Project directories created\"\n\n# Step 6: Verify QpiAI SDK\necho \"\"\nlog_info \"STEP 6: Verifying QpiAI Quantum SDK\"\necho \"─────────────────────────────────────────────────────────────────────\"\n\npython3 -c \"import qpiai_quantum; print(f'✓ QpiAI Quantum SDK v{qpiai_quantum.__version__}')\" 2>/dev/null || {\n    log_error \"QpiAI Quantum SDK verification failed\"\n    exit 1\n}\nlog_success \"QpiAI Quantum SDK verified\"\n\n# Step 7: Summary\necho \"\"\necho \"═══════════════════════════════════════════════════════════════════════\"\necho \"  ✅ DEPLOYMENT PREPARATION COMPLETE\"\necho \"═══════════════════════════════════════════════════════════════════════\"\necho \"\"\necho -e \"${GREEN}Next Steps:${NC}\"\necho \"  1. Update .env with QPIAI_API_KEY\"\necho \"  2. Run 'npm run dev' for local testing\"\necho \"  3. Deploy via: lovable deploy\"\necho \"\"\necho -e \"${BLUE}Documentation:${NC}\"\necho \"  • INSTALLATION.md - Full setup guide\"\necho \"  • CREDITS.md - Attribution & licensing\"\necho \"  • API Docs: http://localhost:5000/api/docs\"\necho \"\"\necho \"═══════════════════════════════════════════════════════════════════════\"\n"